export const chapters = [
{ slug:'histoire', n:'01', tag:'Histoire', title:'Histoire du café', short:'Des hauts plateaux d’Afrique de l’Est aux cafés du monde.',
 img:'ch-histoire', alt:'Illustration générée : route caravanière, mer Rouge et branche de caféier',
 lead:'L’histoire du café mêle botanique, religion, commerce, pouvoir et colonisation. Les récits légendaires circulent beaucoup ; seuls les faits documentés sont affichés ici, avec leur source.',
 points:['L’Arabica est une plante native des hautes terres d’Afrique de l’Est, mais la boisson est née dans le monde islamique [[bm]].','Peu de preuves écrites avant le début du XVIe siècle ; un petit commerce Éthiopie–Yémen existe dès le milieu du XVe [[ucsc]].','Le café reste presque exclusivement islamique jusqu’au milieu du XVIIe siècle, puis gagne l’Europe [[ucsc]].'],
 sections:[
 ['Origines : plante africaine, boisson islamique','<p>Le caféier Arabica est natif des hautes terres d’Afrique de l’Est, tandis que la boisson a ses racines dans le monde islamique [[bm]]. La région de la mer Rouge, côté yéménite et côté éthiopien, est celle où le café apparaît dans les sources [[bbc]].</p><p>Il existe des légendes d’origine. Elles ne constituent pas des sources et ne sont pas reprises comme des faits.</p><figure class="arch-fig"><img src="img/histoire-frise.svg" width="1200" height="360" loading="lazy" decoding="async" alt="Schéma : frise des repères documentés, des soufis du Yémen au monopole de Moka"><figcaption>Frise des repères documentés [[ucsc]] [[folger]] [[bm]]. Les récits légendaires d’origine ne sont pas retenus comme des faits.</figcaption></figure>'],
 ['Yémen et soufisme','<p>Au XVe siècle, des soufis du Yémen buvaient la qahwa pour rester éveillés pendant les longues nuits de récitation du zikr [[folger]]. Un petit commerce de café entre l’Éthiopie et le Yémen est attesté à partir du milieu du XVe siècle [[ucsc]].</p><figure class="arch-fig"><img src="img/ethiopian-coffee-ceremony-ccby.jpg" width="960" height="640" loading="lazy" decoding="async" alt="Photographie : préparation du café lors d’une cérémonie traditionnelle en Éthiopie"><figcaption>Cérémonie du café en Éthiopie, région d’origine de l’Arabica, avant la diffusion de la boisson côté yéménite. <span class="arch-credit">Photographie : Steve Evans, <a href="https://commons.wikimedia.org/wiki/File:Ethiopian_Coffee_Ceremony_011.jpg" rel="noopener">CC BY 2.0, via Wikimedia Commons</a>.</span></figcaption></figure>'],
 ['Moka et le monopole yéménite','<p>Jusqu’à la fin du XVIIe siècle, la production et la distribution du café restent concentrées au Yémen et au port de Moka [[ucsc]]. Les noms « Mocha » et « Java » désignent à l’origine des cafés vendus depuis les ports qui les portent, un héritage resté dans le langage [[ucsc]].</p>'],
 ['Cafés, pouvoir et contrôle','<p>Les maisons de café inquiètent parfois les autorités. Le sultan Murat IV ordonne en 1623 la destruction complète des cafés d’Istanbul [[ucsc]].</p>'],
 ['Europe, colonies et esclavage','<p>Le café arrive en Europe au XVIIe siècle et devient une marchandise mondiale lorsque les Européens le cultivent dans leurs colonies d’Amérique latine, d’Afrique et d’Asie [[ucsc]]. Aux Indes néerlandaises, sur l’île de Java, le café était prélevé sur les paysans comme impôt en nature [[ucsc]]. Le café a fait partie du système esclavagiste et du colonialisme [[ucsc]]. Cette histoire est présentée sans l’adoucir.</p>']
 ],
 terms:['Arabica','Moka','Qahwa'], refs:['bm','ucsc','folger','bbc'] },
{ slug:'botanique', n:'02', tag:'Botanique', title:'Botanique et diversité', short:'Espèces, génétique, variétés et menaces.',
 img:'ch-botanique', alt:'Illustration générée : planche botanique d’une branche de caféier avec fleurs, cerises et coupe de la graine',
 lead:'Le café est une graine de la famille des Rubiacées. Deux espèces font l’essentiel du commerce : Arabica et Canephora (robusta). La diversité sauvage est, elle, fragile.',
 points:['Le genre Coffea compte au moins 124 espèces connues [[ars]] ; 60 % des espèces sauvages sont menacées d’extinction [[kew]].','L’Arabica est un hybride allotétraploïde entre C. canephora et C. eugenioides, avec 44 chromosomes [[pubmed99]] [[nature]].','L’Arabica est la source d’environ 60 % des produits à base de café dans le monde [[nature]].'],
 sections:[
 ['Arabica : un hybride récent','<p>Coffea arabica est un allotétraploïde (2n = 44) issu de l’hybridation de C. canephora et C. eugenioides [[pubmed99]]. Il est la source d’environ 60 % des produits à base de café dans le monde ; ses lignées cultivées ont connu plusieurs goulots d’étranglement génétiques [[nature]].</p><figure class="arch-fig"><img src="img/botanique-hybridation.svg" width="1200" height="360" loading="lazy" decoding="async" alt="Schéma : Coffea canephora et Coffea eugenioides s’hybrident en Coffea arabica, 44 chromosomes"><figcaption>Origine hybride de l’Arabica [[pubmed99]] [[nature]]. Schéma de principe réalisé pour le site.</figcaption></figure><figure class="arch-fig tall"><img src="img/coffee-flower-cc0.webp" width="1200" height="1600" loading="lazy" decoding="async" alt="Photographie : fleurs blanches de Coffea arabica sur leur branche"><figcaption>Fleurs de caféier Arabica (Colombie). L’Arabica est autogame : il peut s’autopolliniser [[fao]]. <span class="arch-credit">Photographie : Roger Burger, <a href="https://commons.wikimedia.org/wiki/File:Coffee_arabica_flower.jpg" rel="noopener">CC0, via Wikimedia Commons</a>.</span></figcaption></figure>'],
 ['Canephora (robusta) et Arabica : différences de plante','<p>Selon la FAO, l’Arabica est autogame (il peut s’autopolliniser), alors que le robusta est allogame ; les feuilles du robusta sont beaucoup plus grandes [[fao]].</p><figure class="arch-fig"><img src="img/arabica-canephora-botany-web.webp" width="1600" height="1067" loading="lazy" decoding="async" alt="Illustration : deux planches botaniques comparées de caféiers, feuilles, fleurs et cerises"><figcaption>Deux caféiers comparés en planches de type botanique. <span class="arch-credit">Illustration générée pour le site, à valeur éditoriale, pas un document botanique de référence.</span></figcaption></figure>'],
 ['Un genre riche, des espèces menacées','<p>Le genre Coffea comprend au moins 124 espèces réparties en Afrique, à Madagascar et dans la zone Asie-Pacifique [[ars]]. L’évaluation de la Liste rouge de l’UICN, menée par Kew sur ces 124 espèces, conclut que 60 % sont menacées d’extinction [[kew]] [[sciadv]]. Les espèces sauvages comptent pour améliorer les variétés cultivées [[sciadv]].</p><figure class="arch-fig"><img src="img/botanique-especes-menacees.svg" width="1200" height="400" loading="lazy" decoding="async" alt="Schéma : 124 espèces de Coffea, 60 pour cent menacées d extinction"><figcaption>Le genre Coffea et la part d espèces menacées selon l UICN [[ars]] [[kew]] [[sciadv]]. <span class="arch-credit">Schéma réalisé pour le site.</span></figcaption></figure>'],
 ['Variétés et résistance','<p>Une étude coordonnée par World Coffee Research a comparé en 2025 la réponse de 29 variétés d’Arabica à la rouille dans 15 pays et sur 23 sites [[wcr2025]]. Selon cette étude, les variétés répondent différemment à la maladie selon les conditions ; le choix d’une variété est donc à apprécier localement (lecture du site, pas une conclusion de l’étude).</p><figure class="arch-fig"><img src="img/botanique-varietes-rouille.svg" width="1200" height="400" loading="lazy" decoding="async" alt="Schéma : étude World Coffee Research 2025 : 29 variétés, 15 pays, 23 sites"><figcaption>L essai international de variétés face à la rouille [[wcr2025]]. <span class="arch-credit">Schéma réalisé pour le site.</span></figcaption></figure>'],
 ['Rouille et scolyte','<p>La crise de la rouille en Amérique centrale, à partir de 2011-2012, a révélé un manque d’informations sur les bonnes pratiques de lutte [[wcrrust]]. Une revue systématique examine la gestion de la rouille et du scolyte du fruit en systèmes agroforestiers [[agrof]].</p><figure class="arch-fig"><img src="img/botanique-rouille-crise.svg" width="1200" height="400" loading="lazy" decoding="async" alt="Schéma : rouille et scolyte du fruit : crise de 2011-2012 et gestion agroforestière"><figcaption>Rouille et scolyte, deux bioagresseurs suivis de près [[wcrrust]] [[agrof]]. <span class="arch-credit">Schéma réalisé pour le site.</span></figcaption></figure>'],
 ['Anatomie de la cerise','<p>Le fruit du caféier est une drupe : un fruit charnu dont la paroi se différencie en exocarpe, mésocarpe et endocarpe autour de la graine [[rsc]]. Une cerise contient généralement deux graines, entourées de peau, pulpe, mucilage, parchemin et pellicule argentée [[coffearium]] [[echo]].</p><figure class="arch-fig"><img src="img/coffee-cherry-anatomy.svg" width="1200" height="800" loading="lazy" decoding="async" alt="Schéma : coupe d’une cerise de café, de la peau à la graine"><figcaption>Coupe d’une cerise de café : peau, pulpe, mucilage, parchemin, pellicule argentée et graine [[coffearium]] [[echo]]. <span class="arch-credit">Schéma réalisé pour le site, à valeur pédagogique.</span></figcaption></figure>']
 ],
 terms:['Arabica','Canephora','Cerise','Mucilage'], refs:['ars','kew','sciadv','pubmed99','nature','fao','wcr2025','wcrrust','agrof','rsc','coffearium','echo'] },
{ slug:'agronomie', n:'03', tag:'Agronomie', title:'Culture et agronomie', short:'Climat, altitude, pluie et changement climatique.',
 img:'ch-agronomie', alt:'Illustration générée : plantation de caféiers ombragée à l’heure dorée',
 lead:'La qualité d’un café se prépare dans le champ. Climat, altitude et pluie fixent déjà beaucoup de ce que la tasse peut offrir.',
 points:['Le café se cultive entre 25° nord et 25° sud, avec des exigences précises selon l’espèce [[fao]].','Températures idéales moyennes : 15–24 °C pour l’Arabica, 24–30 °C pour le robusta [[fao]].','Étude de 2017 (Éthiopie) : les zones actuelles de culture pourraient reculer jusqu’à 60 % dans le scénario le plus pessimiste (+4 °C d’ici 2100) ; des scénarios plus modérés donnent des pertes moindres [[moat]] [[moatbbc]].'],
 sections:[
 ['Température et gel','<p>Les températures moyennes idéales vont de 15 à 24 °C pour l’Arabica et de 24 à 30 °C pour le robusta, qui supporte la chaleur et la sécheresse mais pas les températures nettement inférieures à 15 °C. Tous les caféiers craignent le gel [[fao]].</p><figure class="arch-fig"><img src="img/agronomie-climat.svg" width="1200" height="400" loading="lazy" decoding="async" alt="Schéma : zone de culture entre 25 degrés nord et sud, températures de l’arabica et du robusta, pluie annuelle"><figcaption>Zone tropicale de culture et repères de température et de pluie [[fao]]. Schéma réalisé pour le site.</figcaption></figure>'],
 ['Altitude','<p>Le robusta se cultive du niveau de la mer à environ 800 m ; l’Arabica donne de meilleurs résultats en altitude, souvent en zone vallonnée [[fao]].</p><figure class="arch-fig"><img src="img/agronomie-altitude.svg" width="1200" height="400" loading="lazy" decoding="async" alt="Schéma : robusta du niveau de la mer à 800 m, arabica meilleur en altitude"><figcaption>Les étages de culture du robusta et de l arabica [[fao]]. <span class="arch-credit">Schéma réalisé pour le site.</span></figcaption></figure>'],
 ['Pluie','<p>Le café demande en général 1 500 à 3 000 mm de pluie par an ; le besoin dépend de la rétention du sol, de l’humidité de l’air, de la nébulosité et des pratiques [[fao]].</p><figure class="arch-fig"><img src="img/agronomie-pluie.svg" width="1200" height="400" loading="lazy" decoding="async" alt="Schéma : besoin en pluie du caféier : 1 500 à 3 000 mm par an"><figcaption>Le besoin en eau du caféier et ce qui le fait varier [[fao]]. <span class="arch-credit">Schéma réalisé pour le site.</span></figcaption></figure>'],
 ['Changement climatique','<p>Une étude publiée en 2017 (Nature Plants, Kew et partenaires éthiopiens) modélise l’Éthiopie : les zones actuelles de culture du café pourraient diminuer jusqu’à 60 % pour une hausse de 4 °C d’ici la fin du siècle, scénario d’émissions élevées du GIEC ; avec des scénarios plus modérés, la perte est plus faible. Le résultat vaut pour l’Éthiopie et ces hypothèses, pas pour le café en général [[moat]] [[moatbbc]].</p><figure class="arch-fig"><img src="img/agronomie-climat-ethiopie.svg" width="1200" height="400" loading="lazy" decoding="async" alt="Schéma : Éthiopie : jusqu à 60 pour cent de zones de culture en moins avec plus 4 degrés"><figcaption>La modélisation climatique de l Éthiopie et sa portée [[moat]] [[moatbbc]]. <span class="arch-credit">Schéma réalisé pour le site.</span></figcaption></figure>'],
 ['Ombrage et agroforesterie','<p>L’effet de l’ombrage sur le rendement fait l’objet d’un long débat dans la recherche, avec des résultats contrastés selon les variétés [[shade22]]. Une synthèse indique que des niveaux d’ombrage intermédiaires (environ 35 à 50 %) donnent les rendements les plus élevés, avec des comparaisons difficiles d’une région à l’autre [[shade14]]. Pour le robusta, l’ombrage protège des variations de température, de l’érosion et du rayonnement, mais comporte des compromis de production [[shaderob]]. Les pratiques agroforestières sont aussi étudiées pour la gestion de la rouille et du scolyte [[agrof]].</p><figure class="arch-fig"><img src="img/shade-coffee-guatemala-pd.webp" width="1200" height="814" loading="lazy" decoding="async" alt="Photographie : caféiers cultivés sous un couvert forestier dense"><figcaption>Caféiers sous ombrage forestier traditionnel (Guatemala) ; l’effet de l’ombrage sur le rendement fait l’objet d’un débat de recherche [[shade22]]. <span class="arch-credit">Photographie : John Blake, <a href="https://commons.wikimedia.org/wiki/File:Shade_grown_coffee_in_Guatemala.jpg" rel="noopener">domaine public, via Wikimedia Commons</a>.</span></figcaption></figure>'],
 ['Récolte','<p>Dans la grande majorité des pays producteurs, le café est cueilli à la main ; pour une bonne qualité, les cerises doivent être cueillies une à une, seulement mûres [[faoharv]]. Le code d’usages du Codex distingue quatre systèmes : égrappage en un passage, égrappage en plusieurs passages, cueillette sélective en plusieurs passages et récolte mécanique [[codex]].</p><figure class="arch-fig"><img src="img/agronomie-recolte-4-systemes.svg" width="1200" height="430" loading="lazy" decoding="async" alt="Schéma : quatre systèmes de récolte reconnus par le Codex"><figcaption>Les quatre systèmes de récolte du code d usages du Codex [[faoharv]] [[codex]]. <span class="arch-credit">Schéma réalisé pour le site.</span></figcaption></figure>']
 ],
 terms:['Agroforesterie','Terroir','Rouille orangée','Altitude'], refs:['fao','moat','moatbbc','agrof','shade22','shade14','shaderob','faoharv','codex'] },
{ slug:'post-recolte', n:'04', tag:'Post-récolte', title:'Post-récolte', short:'Fermentation, séchage et café vert.',
 img:'ch-postrecolte', alt:'Illustration générée : cerises de café en séchage sur lits surélevés',
 lead:'Entre la cerise cueillie et le café vert, la transformation influence la qualité finale. Les sources citées ici décrivent surtout les méthodes naturelle, semi-lavée et lavée.',
 points:['Le manuel FAO (Laos) vise un café vert à 12 % d’humidité pour l’export ou la torréfaction. C’est la cible de ce manuel, pas une norme universelle [[faopost]].','Trois méthodes de base : naturelle, semi-lavée, lavée. Elles diffèrent par le retrait du mucilage, l’eau et le risque de fermentation [[faopost]].','Selon ce manuel, une qualité perdue par surfermentation, moisissure, odeur ou dommage au grain ne se récupère pas [[faopost]].'],
 sections:[
 ['Du fruit au café vert','<p>Selon le manuel FAO pour le Laos, la transformation mène la cerise fraîche à un grain vert propre à 12 % d’humidité. La chaîne citée comprend récolte, dépulpage, fermentation, lavage, séchage, décorticage, nettoyage, classement, stockage et transport ; elle varie selon la méthode : la voie naturelle saute le dépulpage, la semi-lavée la fermentation [[faopost]].</p><figure class="arch-fig"><img src="img/postrecolte-methodes.svg" width="1200" height="470" loading="lazy" decoding="async" alt="Schéma comparatif des voies naturelle, semi-lavée et lavée, du fruit au café vert"><figcaption>Les trois voies de transformation décrites par le manuel FAO [[faopost]]. Schéma réalisé pour le site.</figcaption></figure>'],
 ['Voie lavée','<p>Dans la description du manuel FAO : dépulpage à l’eau, puis le mucilage (couche sucrée) fermente un à deux jours, puis lavage à fond du parchemin, séché jusqu’à 12 %. Le manuel indique 2 à 10 L d’eau par kg de cerises fraîches et une gestion fine de la fermentation [[faopost]].</p><figure class="arch-fig"><img src="img/postrecolte-voie-lavee.svg" width="1200" height="430" loading="lazy" decoding="async" alt="Schéma : quatre étapes de la voie lavée : dépulpage, fermentation, lavage, séchage"><figcaption>Les étapes de la voie lavée selon le manuel FAO [[faopost]]. <span class="arch-credit">Schéma réalisé pour le site.</span></figcaption></figure>'],
 ['Voie semi-lavée','<p>Après dépulpage, le mucilage est retiré mécaniquement par un démucilageur, sans fermentation. Le manuel indique environ 0,5 L d’eau par kg de cerises fraîches, mesuré lors d’études au Laos et au Myanmar [[faopost]].</p><figure class="arch-fig"><img src="img/postrecolte-semi-lavee.svg" width="1200" height="400" loading="lazy" decoding="async" alt="Schéma : dépulpage puis démucilageur sans fermentation, environ 0,5 litre d eau par kg"><figcaption>La voie semi-lavée sans fermentation et sa consommation d eau mesurée [[faopost]]. <span class="arch-credit">Schéma réalisé pour le site.</span></figcaption></figure>'],
 ['Voie naturelle','<p>Opération en une étape : le grain sèche dans le fruit entier jusqu’à 12 %, puis la cerise sèche est décortiquée. Le manuel la juge peu coûteuse mais de qualité basse et non recommandée, dans le contexte du Laos où elle sert surtout au robusta. Ce jugement est celui du manuel, d’autres sources décrivent des cafés naturels de grande qualité (à documenter) [[faopost]].</p><figure class="arch-fig"><img src="img/coffee-drying-uganda-ccbysa.webp" width="1200" height="900" loading="lazy" decoding="async" alt="Photographie : cerises de café rouges étalées sur des claies de séchage, deux femmes trient à la main"><figcaption>Cerises en séchage sur claies (Ouganda) : la voie naturelle sèche le fruit entier [[faopost]]. <span class="arch-credit">Photographie : Philip Asedri Dradrio, <a href="https://commons.wikimedia.org/wiki/File:Women_drying_coffee.jpg" rel="noopener">CC BY-SA 4.0, via Wikimedia Commons</a>.</span></figcaption></figure>'],
 ['Lots et contamination','<p>Selon le manuel FAO, toute partie fermentée de la veille contamine les cerises fraîchement récoltées et dégrade tout le lot [[faopost]]. Une sélection rigoureuse des cerises rouges mûres facilite le dépulpage et le classement [[faopost]].</p><figure class="arch-fig"><img src="img/postrecolte-contamination.svg" width="1200" height="400" loading="lazy" decoding="async" alt="Schéma : schéma : restes fermentés de la veille, contamination, lot dégradé"><figcaption>La chaîne de contamination décrite par le manuel FAO [[faopost]]. <span class="arch-credit">Schéma réalisé pour le site.</span></figcaption></figure>'],
 ['Procédé honey','<p>Un « honey » est un café dépulpé puis séché avec son mucilage collant ; les définitions précises varient d’un producteur à l’autre [[dcn]]. Au Costa Rica, on distingue généralement trois degrés, du jaune au rouge puis au noir [[barista]]. Ces appellations ne sont pas normalisées : demandez le procédé réel.</p><figure class="arch-fig"><img src="img/coffee-drying-process-web.webp" width="1600" height="1067" loading="lazy" decoding="async" alt="Illustration : claies de séchage de cerises de café en plein soleil"><figcaption>Le séchage sur lits surélevés, utilisé aussi pour les cafés honey [[dcn]]. <span class="arch-credit">Illustration générée pour le site, sans lieu réel représenté.</span></figcaption></figure>']
 ],
 terms:['Mucilage','Parchemin','Fermentation','Café vert'], refs:['faopost','dcn','barista'] },
{ slug:'torrefaction', n:'05', tag:'Torréfaction', title:'Torréfaction', short:'Chaleur, craquements et réactions chimiques.',
 img:'ch-torrefaction', alt:'Illustration générée : torréfacteur à tambour en cours de torréfaction',
 lead:'La torréfaction transforme un grain vert en café aromatique. Elle suit des étapes thermiques repérables, dont les craquements.',
 points:['Selon le Coffee Research Institute, qui cite l’ouvrage de Davids : premier crack vers 205 °C, volume doublé, perte d’environ 5 % de masse. Ce sont des repères indicatifs, pas des constantes [[roast]].','Même source : de 205 à environ 220 °C, couleur brun moyen et perte d’environ 13 % [[roast]].','Le second crack suit une courte phase endothermique [[roast]].'],
 sections:[
 ['Premier crack','<p>Selon le Coffee Research Institute, autour de 205 °C (400 °F), le grain double de volume, devient brun clair et perd environ 5 % de sa masse [[roast]].</p><figure class="arch-fig"><img src="img/torrefaction-etapes.svg" width="1200" height="360" loading="lazy" decoding="async" alt="Schéma : étapes repères de la torréfaction, du grain vert au second crack"><figcaption>Étapes repères et pertes de masse indicatives [[roast]]. Schéma réalisé pour le site.</figcaption></figure>'],
 ['Au-delà du premier crack','<p>De 205 °C à environ 220 °C, la couleur passe du brun clair au brun moyen et la perte de masse atteint environ 13 % ; une courte phase endothermique précède le second crack [[roast]]. La même page recommande, comme avis de ses auteurs, de ne pas torréfier bien au-delà du début du second crack ; c’est une préférence de goût, pas une règle [[roast]]. Les températures varient avec la machine, la charge et le capteur.</p><figure class="arch-fig"><img src="img/drum-roaster-ccbysa.webp" width="1200" height="900" loading="lazy" decoding="async" alt="Photographie : torréfacteur à tambour ouvert dans un atelier"><figcaption>Torréfacteur à tambour (Eugene, Oregon, États-Unis). Les températures affichées varient avec la machine, la charge et le capteur [[roast]]. <span class="arch-credit">Photographie : Visitor7, <a href="https://commons.wikimedia.org/wiki/File:Last_Stand_Coffee_Roaster_(Eugene,_Oregon).jpg" rel="noopener">CC BY-SA 3.0, via Wikimedia Commons</a>.</span></figcaption></figure>'],
 ['Chimie : Maillard et caramélisation','<p>La réaction de Maillard progresse rapidement entre environ 140 et 165 °C, dans une plage plus large en pratique dans la matrice du grain [[maillard]].</p><figure class="arch-fig"><img src="img/atlas-roast-microscopy-web.jpg" width="1500" height="1125" loading="lazy" decoding="async" alt="Illustration : coupe stylisée d’un grain de café torréfié et détails de structure"><figcaption>Le grain pendant la torréfaction : couleur, structure et réactions chimiques [[maillard]]. <span class="arch-credit">Illustration générée pour le site, à valeur éditoriale, pas une micrographie réelle.</span></figcaption></figure>'],
 ['Repos et dégazage','<p>La torréfaction forme des gaz, dont une grande part de dioxyde de carbone ; une partie est libérée pendant la torréfaction, une partie reste piégée dans la structure poreuse du grain [[degasacs]]. Une étude de torréfacteur sur 21 cafés indique qu’un repos de 24 heures peut ne pas suffire pour atteindre la qualité maximale ; elle ne vaut que pour ses conditions d’essai [[restudy]].</p><figure class="arch-fig"><img src="img/torrefaction-degazage.svg" width="1200" height="400" loading="lazy" decoding="async" alt="Schéma : grain de café : gaz libérés pendant la torréfaction, une partie reste piégée"><figcaption>Gaz formés à la torréfaction et repos du grain [[degasacs]] [[restudy]]. <span class="arch-credit">Schéma réalisé pour le site.</span></figcaption></figure>']
 ],
 terms:['Maillard','Crack','Dégazage'], refs:['roast','maillard','degasacs','restudy'] },
{ slug:'extraction', n:'06', tag:'Extraction', title:'Extraction et préparation', short:'Force, extraction, eau et ratio.',
 img:'ch-extraction', alt:'Illustration générée : préparation d’un café filtre avec bouilloire à col de cygne',
 lead:'Préparer un café, c’est dissoudre une partie des composés du grain. La norme « Golden Cup » donne des repères mesurables pour le café filtre.',
 points:['Force cible : 1,15 à 1,35 % de matières dissoutes (TDS), pour un rendement d’extraction de 18 à 22 % [[golden]] [[goldencrit]].','Eau à environ 93 °C ± 3 au contact du café [[golden]].','Ces repères valent pour le café filtre et viennent d’un travail de 1957 : ce n’est pas une loi universelle [[goldencrit]].'],
 sections:[
 ['La norme Golden Cup','<p>Elle définit un point de rencontre entre force (TDS) et rendement d’extraction, auquel des panels entraînés et des consommateurs ont jugé le café équilibré [[golden]]. Plage de force : 1,15 à 1,35 % ; rendement : 18 à 22 % [[golden]] [[goldencrit]].</p><figure class="arch-fig"><img src="img/extraction-golden-cup.svg" width="1200" height="460" loading="lazy" decoding="async" alt="Schéma : graphique force et rendement, zone Golden Cup en surbrillance"><figcaption>Le point de rencontre entre force (1,15–1,35 %) et rendement (18–22 %) [[golden]] [[goldencrit]]. <span class="arch-credit">Schéma réalisé pour le site.</span></figcaption></figure>'],
 ['Eau et ratio','<p>Température de l’eau : 93 °C ± 3 au contact du café [[golden]]. Un module de formation SCA cite environ 55 g de café par litre d’eau, soit un ratio proche de 1:18 [[scatrain]]. Des guides pratiques reprennent aussi des ratios de 1:16 à 1:17 pour le filtre (source secondaire) [[ratio16]].</p><figure class="arch-fig"><img src="img/v60-pourover-ccby.webp" width="1200" height="675" loading="lazy" decoding="async" alt="Photographie : café moulu mouillé dans un filtre V60, vu du dessus"><figcaption>Préparation douce en V60 : le mouillage initial de la mouture (« bloom »). <span class="arch-credit">Photographie : Indigo.udm, <a href="https://commons.wikimedia.org/wiki/File:Tasty_Coffee_pourover_V60_bloom_2025.jpg" rel="noopener">CC BY 4.0, via Wikimedia Commons</a>.</span></figcaption></figure><p><a href="outils.html">Ouvrir le calculateur du Laboratoire →</a></p>'],
 ['Limites de la norme','<p>Les deux plages 1,15–1,35 % et 18–22 % sont réelles, mais viennent d’un article de 1957 et décrivent le café filtre ; elles ne couvrent pas l’espresso [[goldencrit]].</p><figure class="arch-fig"><img src="img/extraction-golden-limites.svg" width="1200" height="400" loading="lazy" decoding="async" alt="Schéma : deux cartes : ce que la norme couvre, ce qu elle ne couvre pas"><figcaption>Les plages viennent d un article de 1957 et décrivent le café filtre, pas l espresso [[goldencrit]]. <span class="arch-credit">Schéma réalisé pour le site.</span></figcaption></figure>'],
 ['Mouture','<p>La taille de mouture influe sur la vitesse d’extraction, par la surface de contact, et sur la vitesse d’écoulement de l’eau à travers le lit de café [[scatrain]]. Le diagnostic du goût, l’espresso, le piston et le moka sont détaillés dans les sections suivantes.</p><figure class="arch-fig"><img src="img/extraction-methodes.svg" width="1200" height="430" loading="lazy" decoding="async" alt="Schéma comparatif : espresso, filtre, piston et moka, avec leurs repères"><figcaption>Quatre méthodes, quatre jeux de repères issus des sources citées [[scaespresso]] [[golden]] [[rocpress]] [[bialetti]]. Schéma réalisé pour le site.</figcaption></figure>'],
 ['Diagnostiquer une tasse : acide ou amère ?','<p>Des essais sensoriels de l’UC Davis Coffee Center, avec des dégustateurs entraînés, ont fait varier la force (TDS) et le rendement d’extraction (PE) du café filtre. Résultats : l’amertume augmente avec la force et avec le rendement (mesure faite sur une torréfaction moyenne) ; l’acidité (sourness) augmente avec la force mais diminue quand le rendement augmente ; la douceur naturelle diminue avec la force et avec le rendement [[scabrew]].</p><p>Lecture pratique : une tasse très acide correspond plutôt à un faible rendement, une tasse très amère à un rendement élevé. Ce sont des tendances statistiques sur des échantillons contrôlés, pas des règles pour une tasse isolée. Les auteurs notent que la carte classique de Lockhart (1957) ne retient que deux attributs, « amer » et « sous-développé », et qu’elle mélange description du goût et préférence des consommateurs [[scabrew]].</p><figure class="arch-fig"><img src="img/extraction-diagnostic.svg" width="1200" height="470" loading="lazy" decoding="async" alt="Schéma : tableau des tendances mesurées : amertume, acidité, douceur selon force et rendement"><figcaption>Tendances mesurées par l UC Davis Coffee Center sur torréfaction moyenne [[scabrew]]. <span class="arch-credit">Schéma réalisé pour le site.</span></figcaption></figure>'],
 ['Espresso : repères et pratiques','<p>La définition historique de la SCAA, republiée par la SCA, décrit un espresso de 25 à 35 ml préparé avec 7 à 9 g de café (14 à 18 g pour un double), une eau à 90,5–96,1 °C, une pression de 9 à 10 atmosphères et une mouture telle que le temps d’extraction soit de 20 à 30 secondes [[scaespresso]].</p><p>Une enquête 2017 de la Barista Guild of America auprès de baristas du monde entier décrit les pratiques réelles : ratio moyen de 1:2 (de 1:1,5 à 1:2,5), environ 36,5 g de boisson pour 18 à 20 g de café, 25 à 30 secondes pour 51 % des répondants, 9 bars pour la réponse la plus fréquente [[scaespresso]]. Ce sont des pratiques déclarées, pas une norme : le café filtre et l’espresso n’obéissent pas aux mêmes repères (voir « Limites de la norme »).</p><figure class="arch-fig"><img src="img/extraction-espresso-reperes.svg" width="1200" height="430" loading="lazy" decoding="async" alt="Schéma : comparaison définition historique SCAA et pratiques réelles des baristas en 2017"><figcaption>Définition SCAA et pratiques réelles relevées par la Barista Guild of America (2017) [[scaespresso]]. <span class="arch-credit">Schéma réalisé pour le site.</span></figcaption></figure>'],
 ['Piston (cafetière à immersion)','<p>Le piston est une extraction par immersion : le café et l’eau infusent ensemble avant que le filtre à piston retienne le marc [[rocpress]]. Le module de formation ROCC (SCA Training) propose un ratio de 1:15 (par exemple 26 g de café pour 400 ml d’eau, ou 55 g pour 950 ml), une cafetière rincée et préchauffée, un tiers de l’eau versé d’abord pour mouiller tout le café, puis le reste, 4 minutes d’attente et une pression lente du piston [[rocpress]]. C’est une recette d’un formateur, pas une norme : le ratio de 1:15 diffère du repère de 1:18 cité pour le filtre.</p><figure class="arch-fig"><img src="img/extraction-piston-etapes.svg" width="1200" height="430" loading="lazy" decoding="async" alt="Schéma : cinq étapes de la recette piston : préchauffer, doser, mouiller, attendre, presser"><figcaption>La recette du module de formation ROCC (SCA Training) en cinq étapes [[rocpress]]. <span class="arch-credit">Schéma réalisé pour le site.</span></figcaption></figure>'],
 ['Moka (cafetière italienne)','<p>Selon Bialetti, le moka utilise la pression de la vapeur : l’eau de la chambre basse, chauffée, est poussée à travers le café puis monte dans la colonne jusqu’au collecteur supérieur ; le grésillement final signale que l’eau est presque épuisée [[bialetti]]. Le fabricant indique une pression d’environ 1,5 bar, contre au moins 9 bars pour une machine espresso, ce qui explique une boisson différente [[bialetti]].</p><p>Conseils du fabricant : eau à température ambiante, plutôt peu dure (calcaire), mouture plus grosse que pour l’espresso, feu doux [[bialetti]]. Ces conseils viennent d’un fabricant, pas d’une étude indépendante.</p><figure class="arch-fig"><img src="img/moka-pot-ccbysa.webp" width="1200" height="900" loading="lazy" decoding="async" alt="Photographie : cafetière moka démontée, chambre basse, filtre et collecteur"><figcaption>Cafetière moka démontée : chambre basse, filtre et collecteur supérieur [[bialetti]]. <span class="arch-credit">Photographie : Coyau, <a href="https://commons.wikimedia.org/wiki/File:Moka_KILT._13.jpg" rel="noopener">CC BY-SA 3.0, via Wikimedia Commons</a>.</span></figcaption></figure>']
 ],
 terms:['Ratio','Mouture','Extraction','TDS'], refs:['golden','scatrain','goldencrit','ratio16','scabrew','scaespresso','rocpress','bialetti'] },
{ slug:'sensoriel', n:'07', tag:'Dégustation', title:'Dégustation et sensoriel', short:'Cupping, CVA et roue des arômes.',
 img:'ch-sensoriel', alt:'Illustration générée : table de cupping avec tasses, cuillères et carnet',
 lead:'Goûter, c’est apprendre à nommer. La SCA a publié des normes de dégustation qui séparent la description objective de l’appréciation personnelle.',
 points:['La SCA a adopté trois composantes du « Coffee Value Assessment » comme normes de cupping : SCA-102, SCA-103 et SCA-104 [[cva]].','La Coffee Taster’s Flavor Wheel date de 1995 et a été mise à jour en 2016 avec World Coffee Research [[scastore]].','Évaluation descriptive : arôme, saveur, texture et arrière-goût, avec un langage standardisé [[cva]].'],
 sections:[
 ['Les normes de cupping SCA','<p>SCA-102 porte sur la préparation des échantillons et le cupping, SCA-103 sur l’évaluation descriptive, SCA-104 sur l’évaluation affective [[cva]].</p><figure class="arch-fig"><img src="img/coffee-cupping-sensory-web.webp" width="1600" height="1067" loading="lazy" decoding="async" alt="Illustration : table de dégustation avec bols de cupping, cuillères, échantillons et roue des arômes"><figcaption>Une table de dégustation : échantillons, bols, cuillères et roue des arômes [[cva]] [[scastore]]. <span class="arch-credit">Illustration générée pour le site, sans lieu réel représenté.</span></figcaption></figure>'],
 ['La roue des arômes','<p>La Coffee Taster’s Flavor Wheel, publiée en 1995, a été mise à jour en 2016 en collaboration avec World Coffee Research [[scastore]]. Le Laboratoire du site propose une roue interactive.</p><p><a href="outils.html">Ouvrir le Laboratoire →</a></p><figure class="arch-fig"><img src="img/sensoriel-roue-dates.svg" width="1200" height="400" loading="lazy" decoding="async" alt="Schéma : frise 1995 publication de la roue des arômes, 2016 mise à jour avec World Coffee Research"><figcaption>De 1995 à la mise à jour de 2016 avec World Coffee Research [[scastore]]. <span class="arch-credit">Schéma réalisé pour le site.</span></figcaption></figure>'],
 ['Pratique du cupping','<p>Le protocole SCA décrit couramment : 8,25 g de café pour 150 ml d’eau (environ 1:18), eau vers 93 °C, croûte brisée après 4 minutes (description par des sources secondaires) [[royal]] [[gota]].</p><figure class="arch-fig"><img src="img/sensoriel-cupping.svg" width="1200" height="270" loading="lazy" decoding="async" alt="Schéma : étapes du protocole de cupping, dose, eau, croûte et dégustation"><figcaption>Les étapes du protocole couramment décrit [[royal]] [[gota]]. Schéma réalisé pour le site.</figcaption></figure>'],
 ['Défauts du café vert','<p>La norme de classification des cafés verts de la SCA définit un défaut comme une propriété du café vert ou torréfié généralement perçue comme négative [[scagreen]]. La FAO présente les principaux systèmes de classification [[faogreen]].</p><figure class="arch-fig"><img src="img/sensoriel-defauts-vert.svg" width="1200" height="400" loading="lazy" decoding="async" alt="Schéma : définition d un défaut du café vert selon la norme SCA et systèmes de classification FAO"><figcaption>La définition d un défaut selon la norme SCA et les systèmes de classification présentés par la FAO [[scagreen]] [[faogreen]]. <span class="arch-credit">Schéma réalisé pour le site.</span></figcaption></figure>']
 ],
 terms:['Cupping','Acidité','Corps','Finale'], refs:['cva','scastore','royal','gota','scagreen','faogreen'] },
{ slug:'sante', n:'08', tag:'Santé', title:'Santé et qualité', short:'Caféine, repères EFSA et sécurité des aliments.',
 img:'ch-sante', alt:'Illustration générée : tasse de café noir à côté d’un verre d’eau et d’un carnet',
 lead:'Cette page présente des repères officiels, pas des conseils médicaux. En cas de doute (grossesse, traitement, maladie), demandez l’avis d’un professionnel de santé.',
 points:['EFSA (2015) : jusqu’à 400 mg de caféine par jour ne soulèvent pas de problème de sécurité pour l’adulte en bonne santé [[efsa]].','Doses uniques jusqu’à 200 mg : pas de problème de sécurité pour l’adulte en bonne santé [[efsa]].','Femmes enceintes ou allaitantes : jusqu’à 200 mg par jour [[efsa]].'],
 sections:[
 ['Adultes en bonne santé','<p>D’après l’avis de l’EFSA de mai 2015, des apports de caféine jusqu’à 400 mg par jour, toutes sources confondues, ne soulèvent pas de problème de sécurité pour la population adulte en bonne santé ; des doses uniques jusqu’à 200 mg non plus [[efsa]] [[efsajour]].</p><figure class="arch-fig"><img src="img/sante-cafeine.svg" width="1200" height="330" loading="lazy" decoding="async" alt="Schéma : barres des repères EFSA 2015, 400 mg par jour adulte, 200 mg dose unique, 200 mg grossesse"><figcaption>Les repères EFSA de 2015 en un coup d’œil [[efsa]] [[efsajour]]. Schéma réalisé pour le site.</figcaption></figure>'],
 ['Grossesse et allaitement','<p>Pour les femmes enceintes ou allaitantes, l’EFSA indique que des apports jusqu’à 200 mg par jour répartis dans la journée ne soulèvent pas de problème de sécurité pour le fœtus [[efsa]].</p>'],
 ['Ochratoxine A','<p>Le règlement (UE) 2022/1370 fixe des teneurs maximales en ochratoxine A de 3,0 µg/kg pour le café torréfié et 5,0 µg/kg pour le café soluble [[ota]]. Ce règlement ne fixe pas de teneur maximale pour le café vert [[ota]].</p>'],
 ['Limites de ce site','<p>Ce site ne formule aucune promesse de santé et ne recommande aucun traitement.</p>']
 ],
 terms:['Caféine','Ochratoxine','Décaféiné'], refs:['efsa','efsajour','ota'] },
{ slug:'filiere', n:'09', tag:'Filière', title:'Filière et marché', short:'Production mondiale et acteurs.',
 img:'ch-professionnels', alt:'Illustration générée : plateaux d’échantillons de café vert, balance et carnet',
 lead:'De la ferme au comptoir, la filière réunit producteurs, exportateurs, importateurs, torréfacteurs et cafés. Les chiffres ci-dessous précisent l’année et le périmètre.',
 points:['Production mondiale 2025/26 : 183,6 millions de sacs de 60 kg, record, contre 175,9 en 2024/25 ; consommation 180,6 M ; excédent de 3,0 M de sacs, le premier depuis 2020/21 après quatre déficits (2021/22 à 2024/25) (OIC, octobre 2026, estimations du secrétariat) [[ico1026]].','Exportations africaines, toutes formes : 17,9 millions de sacs en 2025/26, soit −6,7 % sur 19,19 M en 2024/25 ; l’Éthiopie recule de 8,3 % [[ico1026]].','Prix de référence : indicateur composite OIC (I-CIP) de 261,26 cents US par livre en octobre 2026 [[ico1026]]. Chaîne de valeur et labels : à documenter, aucun chiffre n’est affiché sans source.'],
 sections:[
 ['Chiffres de l’année caféière 2025/26','<p>Source : Coffee Market Report de l’OIC d’octobre 2026 [[ico1026]]. L’année caféière court d’octobre à septembre ; les valeurs sont des estimations du secrétariat, par année caféière. Les estimations par pays servent à établir un bilan mondial cohérent ; elles ne décrivent pas la production relevée sur le terrain dans chaque pays [[ico1026]].</p><figure class="arch-fig"><img src="img/coffee-chain-diagram.svg" width="1200" height="300" loading="lazy" decoding="async" alt="Schéma : la chaîne du café en cinq étapes, de la plante à la tasse"><figcaption>Chaque étape de la chaîne ajoute des variables et des possibilités de perte ou de valeur. <span class="arch-credit">Schéma réalisé pour le site.</span></figcaption></figure><div class="tbl-wrap"><table class="tbl tbl-sm"><caption>Offre et demande mondiales (millions de sacs de 60 kg), OIC, octobre 2026</caption><thead><tr><th scope="col">Indicateur</th><th scope="col">2024/25</th><th scope="col">2025/26</th></tr></thead><tbody><tr><th scope="row">Production totale</th><td>175,9</td><td>183,6</td></tr><tr><th scope="row">Consommation</th><td>182,2</td><td>180,6</td></tr><tr><th scope="row">Équilibre offre et demande</th><td>−6,2</td><td>+3,0</td></tr></tbody></table></div><div class="tbl-wrap"><table class="tbl tbl-sm"><caption>Production par région (millions de sacs de 60 kg), OIC, octobre 2026</caption><thead><tr><th scope="col">Région</th><th scope="col">2024/25</th><th scope="col">2025/26</th></tr></thead><tbody><tr><th scope="row">Asie et Océanie</th><td>50,4</td><td>54,6</td></tr><tr><th scope="row">Amérique du Sud</th><td>82,8</td><td>84,1</td></tr><tr><th scope="row">Amérique centrale et Mexique</th><td>18,9</td><td>19,9</td></tr><tr><th scope="row">Afrique</th><td>23,9</td><td>25,0</td></tr></tbody></table></div><p>Consommation en Afrique : 13,3 M de sacs en 2024/25 et 13,4 M en 2025/26 [[ico1026]].</p><p>Commerce, année caféière 2025/26 (octobre 2025 à septembre 2026) : les exportations mondiales de café vert atteignent 123,93 millions de sacs en 2025/26 (+1,3 % sur 122,33 M), et toutes formes confondues 142,39 M (+1,0 % sur 141,02 M). Le vert représente 87,0 % des exportations, le soluble 12,5 % et le torréfié 0,5 %. Les exportations de café vert de robusta dépassent 50 millions de sacs pour la première fois (50,1 M, +12,3 %), soit 40,4 % des exportations de café vert, tirées par le Viêt Nam (26,37 M de sacs, +26,7 %) [[ico1026]].</p><p><strong>Afrique</strong> : exportations, toutes formes, de 17,9 millions de sacs en 2025/26, soit −6,7 % sur 19,19 M en 2024/25 ; toutes les grandes origines africaines reculent, l’Éthiopie le plus (−8,3 %, soit −0,62 M de sacs) [[ico1026]].</p>'],
 ['Prix de référence (octobre 2026)','<p>Moyennes mensuelles de l’indicateur composite OIC et de ses groupes, en cents US par livre [[ico1026]]. Les prix varient chaque mois ; l’OIC note une hausse des arabicas et une baisse des robustas en octobre 2026, avec des stocks certifiés d’arabica américains à 0,23 M de sacs, plus bas niveau de fin de mois depuis janvier 2002 [[ico1026]].</p><div class="tbl-wrap"><table class="tbl tbl-sm"><caption>Prix moyens, octobre 2026 (cents US par livre), OIC</caption><thead><tr><th scope="col">Indicateur</th><th scope="col">Octobre 2026</th></tr></thead><tbody><tr><th scope="row">I-CIP (composite)</th><td>261,26</td></tr><tr><th scope="row">Colombian Milds</th><td>357,85</td></tr><tr><th scope="row">Other Milds</th><td>334,99</td></tr><tr><th scope="row">Brazilian Naturals</th><td>294,49</td></tr><tr><th scope="row">Robustas</th><td>164,19</td></tr></tbody></table></div><p>Ces prix concernent des groupes de cafés verts négociés sur les marchés internationaux. Ce rapport ne publie pas de prix propre au Bénin ; un prix béninois reste à documenter.</p>'],
 ['Production mondiale en 2022/23 (historique)','<p>Selon l’OIC, la production mondiale a augmenté de 0,1 % à 168,2 millions de sacs de 60 kg en année caféière 2022/23, avec une répartition contrastée entre les Amériques et le reste du monde [[ico23]]. Le rapport met en avant l’effet de la gelée de juillet 2021 sur le Brésil et les Arabicas [[ico23]].</p>'],
 ['Données et statistiques','<p>L’OIC diffuse les volumes et tendances du commerce mondial du café : exportations, importations et réexportations [[icostats]].</p>'],
 ['Acteurs, prix, labels','<p><strong>À documenter</strong> : chaîne de valeur, prix, classement qualité et labels, avec sources. Aucun chiffre n’est affiché tant qu’il n’est pas vérifié.</p><p><a href="professionnels.html">Ouvrir l’espace professionnel →</a></p>']
 ],
 terms:['Coopérative','Traçabilité'], refs:['ico23','icostats'] },
{ slug:'afrique', n:'10', tag:'Afrique', title:'Afrique et Bénin', short:'Producteurs africains, Afrique de l’Ouest, dossier Bénin.',
 img:'atlas-benin-field-notebook-web', alt:'Visuel éditorial du carnet de terrain Bénin (illustration du site)',
 lead:'L’Afrique est le berceau de l’arabica et du robusta. Cette page réunit des repères sourcés pour l’Afrique, le Bénin et l’Afrique de l’Ouest ; les chiffres béninois restent à confirmer.',
 points:['Afrique : berceau de l’arabica et du robusta [[iacoglance]], le continent produit 25,0 millions de sacs en 2025/26 (OIC, octobre 2026) [[ico1026]].','Bénin : 55,13 t de café vert en 2024 dans FAOSTAT, valeur estimée par la FAO (drapeau E), à confirmer auprès de la statistique béninoise [[faobulk]] ; membre fondateur de l’IACO en 1960, sous le nom de Dahomey [[iacoglance]].','Afrique de l’Ouest : la Côte d’Ivoire revient à 1,3 million de sacs en 2025/26 (USDA, juillet 2026) [[usda]] ; la Guinée y était le deuxième producteur dans les moyennes 2010/11–2013/14 de l’OIC [[icoafrica]].'],
 sections:[
 ['L’Afrique, berceau du café','<p>L’Afrique est le continent d’origine des deux espèces de café cultivées dans le monde, l’arabica et le robusta [[iacoglance]]. En 2025/26, le continent produit 25,0 millions de sacs de 60 kg, après 23,9 millions en 2024/25, et il en consomme 13,4 millions [[ico1026]]. Ses exportations, toutes formes confondues, atteignent 17,9 millions de sacs en 2025/26, en baisse de 6,7 % sur un an : toutes les grandes origines africaines reculent, l’Éthiopie le plus fortement (−8,3 %) [[ico1026]].</p><p>Ce poids a longtemps été plus grand : l’Afrique représentait en moyenne 31 % des exportations mondiales dans les années 1970, 24,4 % dans les années 1980 et 19,1 % dans les années 1990. En 2013, ses exportations de café vert valaient 1,8 milliard de dollars sur un total mondial de 15,9 milliards, soit 11,4 % de la valeur, contre 21 % en 1990 [[icoafrica]].</p><p>L’Alliance interafricaine du café (IACO) porte cette filière : organisation intergouvernementale créée le 7 décembre 1960 à Antananarivo par onze pays producteurs, dont le Dahomey, aujourd’hui Bénin, elle réunit 25 pays membres et se donne pour mission de servir les intérêts du café africain et de faire reconnaître ses cafés dans le monde [[iacoglance]].</p>'],
 ['Bénin : chiffres à confirmer','<p>Dans FAOSTAT (fichier QCL du 31 décembre 2025), la production béninoise de café vert est de 55,13 t en 2024 (55,00 t en 2021, 55,30 t en 2022, 55,09 t en 2023), sur 284 ha récoltés, soit 194,5 kg/ha ; toutes les valeurs 2016–2024 portent le drapeau E, valeur estimée par la FAO, et non une statistique nationale déclarée [[faobulk]]. Le même fichier donne un record de 3 000 t en 1984 (drapeau X : chiffre d’une organisation extérieure à la FAO) [[faobulk]] ; des sites secondaires reprennent ces séries [[faostatbj]] [[terra]]. Le bulletin national de la Direction de la Statistique Agricole sur la campagne 2023-2024 présente notamment l’anacarde (203 844 t) mais ne contient pas de ligne consacrée au café : la série nationale du café n’a donc pas pu être recoupée dans ce document [[dsa2324]]. Le rapport OIC de 2015 (source primaire) donne pour le Bénin une production moyenne de 33 000 sacs de 60 kg dans les années 1980 (soit environ 1 980 t, calcul du site) et aucune production enregistrée dans les années 1990, 2000 et en 2013/14 [[icoafrica]] ; un site secondaire reprend ce constat [[beanesis]]. Le décret béninois n° 2001-351 décrit pour sa part, dans les années 1990, environ 150 t par an sur près de 600 ha et des exportations contrôlées de 32,6 t (1991) à 1 850,8 t (1996), ces pics étant attribués en partie à la contrebande de production voisine [[decret]]. Ce ne sont pas les mêmes mesures que les moyennes décennales de l’OIC (un « 0 » en milliers de sacs peut être un arrondi ou une absence d’enregistrement) : on ne peut pas parler de contradiction, mais le décret atteste une activité caféière que l’OIC ne montre pas à son niveau d’arrondi. Pour le chiffre récent, 2013/14 (OIC) et 2024 (FAOSTAT) sont à comparer : <strong>à confirmer</strong> auprès de FAOSTAT, de l’OIC et de la Direction de la Statistique Agricole.</p><p>Une rencontre entre l’Alliance interafricaine du café (IACO) et le gouvernement du Bénin a porté sur le développement de la filière nationale [[iaco]].</p><p><a href="benin.html">Ouvrir le dossier Bénin complet →</a></p>'],
 ['Archives photographiques : caféiers à Zagnanado (vers 1930)','<p>Trois photographies d’archives montrent des plantations de caféiers à Zagnanado, au Dahomey, nom que portait alors le territoire de l’actuel Bénin. Elles sont attribuées au photographe Jean Duprez et conservées par la Bibliothèque nationale de France ; Wikimedia Commons les date de 1930 et les indique dans le domaine public [[duprez]]. Les légendes reprennent les titres de la BnF. Ce sont des documents historiques : ils ne renseignent ni les volumes ni la qualité du café d’aujourd’hui.</p><figure class="arch-fig"><img src="img/zagnanado-1930-jeunes-cafeiers.webp" width="1000" height="577" loading="lazy" decoding="async" alt="Photographie en noir et blanc : un homme debout parmi de jeunes caféiers, avec des palmiers à l’arrière-plan"><figcaption>Jeune plantation de caféiers âgés de 1 an, Zagnanado, Dahomey. <span class="arch-credit">Photographie : Jean Duprez, vers 1930. Bibliothèque nationale de France, domaine public selon <a href="https://commons.wikimedia.org/wiki/File:Jeune_plantation_de_caf%C3%A9iers_%C3%A2g%C3%A9s_de_1_an_%C3%A0_Zagnanado_au_Dahomey_-_Jean_Duprez_-_btv1b10111068n.jpg" rel="noopener">Wikimedia Commons</a>.</span></figcaption></figure><figure class="arch-fig"><img src="img/zagnanado-1930-palmeraie.webp" width="1000" height="579" loading="lazy" decoding="async" alt="Photographie en noir et blanc : caféiers au pied de palmiers à huile, avec des personnes debout au fond"><figcaption>Plantation de caféiers sous palmeraie naturelle, Zagnanado, Dahomey. <span class="arch-credit">Photographie : Jean Duprez, vers 1930. Bibliothèque nationale de France, domaine public selon <a href="https://commons.wikimedia.org/wiki/File:Plantation_de_caf%C3%A9iers_sous_palmeraie_naturelle_%C3%A0_Zagnanado_au_Dahomey_-_Jean_Duprez_-_btv1b101110676.jpg" rel="noopener">Wikimedia Commons</a>.</span></figcaption></figure><figure class="arch-fig tall"><img src="img/zagnanado-1930-arachide.webp" width="640" height="1091" loading="lazy" decoding="async" alt="Photographie en noir et blanc : rangs de caféiers adultes et, au fond, une personne debout et des palmiers"><figcaption>Plantation de caféiers âgés de trois ans, associés à l’arachide (Coffea canephora), Zagnanado, Dahomey. <span class="arch-credit">Photographie : Jean Duprez, vers 1930. Bibliothèque nationale de France, domaine public selon <a href="https://commons.wikimedia.org/wiki/File:Plantation_de_caf%C3%A9iers_%C3%A2g%C3%A9s_de_trois_ans_en_association_avec_de_l%27arachide_%C3%A0_Zagnanado_au_Dahomey_-_Jean_Duprez_-_btv1b10111071x.jpg" rel="noopener">Wikimedia Commons</a>.</span></figcaption></figure>'],
 ['Afrique de l’Ouest','<p>L’Afrique de l’Ouest est une terre de robusta. La Côte d’Ivoire en est le leader historique : 7,1 % des exportations mondiales dans les années 1970, troisième exportateur africain de la décennie 2010 avec 13,4 % des exportations du continent [[icoafrica]], et de retour à 1,3 million de sacs en 2025/26 selon l’USDA [[usda]]. Dans la sous-région, les mouvements coopératifs sont relativement récents [[icoafrica]] ; la recherche ivoirienne (CNRA) figure parmi les institutions africaines qui ont mis au point des caféiers à haut rendement et résistants aux maladies, dont la diffusion aux producteurs reste limitée [[icoafrica]]. La consommation progresse aussi sur place : la Côte d’Ivoire compte parmi les pays africains où elle est en forte hausse [[icoafrica]].</p><p>Repères chiffrés : moyennes des campagnes 2010/11 à 2013/14, tableau 7 du rapport OIC de 2015 (production moyenne, superficie, rendement). Ce sont des moyennes publiées en 2015, pas des chiffres actuels [[icoafrica]].</p><div class="tbl-wrap"><table class="tbl"><caption>Afrique de l’Ouest : production moyenne, superficie et rendement, moyennes 2010/11–2013/14 (OIC, 2015)</caption><thead><tr><th scope="col">Pays</th><th scope="col">Production (milliers de sacs de 60 kg)</th><th scope="col">Superficie (ha)</th><th scope="col">Rendement (kg/ha)</th></tr></thead><tbody><tr><th scope="row">Côte d’Ivoire</th><td>1 753</td><td>360 000</td><td>292</td></tr><tr><th scope="row">Guinée</th><td>374</td><td>46 000</td><td>488</td></tr><tr><th scope="row">Togo</th><td>125</td><td>40 000</td><td>188</td></tr><tr><th scope="row">Sierra Leone</th><td>61</td><td>15 000</td><td>245</td></tr><tr><th scope="row">Ghana</th><td>58</td><td>15 000</td><td>233</td></tr><tr><th scope="row">Nigeria</th><td>43</td><td>50 000</td><td>51</td></tr><tr><th scope="row">Liberia</th><td>10</td><td>2 000</td><td>306</td></tr><tr><th scope="row">Bénin</th><td>0</td><td>15 000</td><td>0</td></tr></tbody></table></div><p>Lecture : la Guinée est, dans ce tableau, le deuxième producteur ouest-africain derrière la Côte d’Ivoire, avec le rendement le plus élevé de la sous-région ; le « 0 » du Bénin peut être un arrondi ou une absence d’enregistrement à cette échelle, pas nécessairement une absence de production (voir la rubrique Bénin). Pour les années récentes, la Guinée, la Sierra Leone et le Togo figurent parmi les pays suivis par l’USDA mais sans ligne dans son tableau récapitulatif, et le Ghana, le Nigeria et le Liberia n’y sont pas cités [[usda]] : la nouvelle rubrique « données récentes et fiches pays » apporte des valeurs FAOSTAT 2024 séparées, avec leurs drapeaux et limites [[faowest]]. La base de l’OIC reste une piste de recoupement [[icostats]]. Le Cameroun, souvent rattaché à l’Afrique centrale, est présenté dans la rubrique « Autres pays africains ».</p>'],
 ["Afrique de l’Ouest : données récentes et fiches pays", "<p>Les chiffres ci-dessous proviennent du fichier intégral FAOSTAT QCL, version mise à jour le 31 décembre 2025, relu le 21 novembre 2026 : produit 656, café vert, années civiles 2022 à 2024 [[faowest]]. Ils ne décrivent ni la campagne 2025/26 ni une prévision pour 2026. Les drapeaux font partie de la donnée : A = chiffre officiel ; E = valeur estimée ; I = valeur imputée par un organisme destinataire ; X = chiffre fourni par une organisation extérieure [[faowest]]. Une valeur estimée ou imputée ne doit pas être présentée comme une mesure nationale récente.</p><figure class=\"arch-fig\"><img src=\"img/afrique-ouest-production.svg\" width=\"1200\" height=\"510\" loading=\"lazy\" decoding=\"async\" alt=\"Schéma : barres de la production 2024 de café vert en Afrique de l’Ouest, Guinée, Côte d’Ivoire, Togo puis les autres pays\"><figcaption>Les mêmes valeurs 2024 en graphique, avec leurs drapeaux FAOSTAT [[faowest]]. Les barres sont à l’échelle linéaire : le Bénin (55 t) y est à peine visible, ce qui illustre l’écart de volumes.</figcaption></figure><div class=\"tbl-wrap\" tabindex=\"0\" role=\"region\" aria-label=\"Données FAOSTAT 2024, tableau défilant horizontalement\"><table class=\"tbl\"><caption>Café vert en 2024 : tonnes, hectares récoltés et rendement (FAOSTAT, avec drapeaux)</caption><thead><tr><th scope=\"col\">Pays</th><th scope=\"col\">Production (t)</th><th scope=\"col\">Surface récoltée (ha)</th><th scope=\"col\">Rendement (kg/ha)</th></tr></thead><tbody><tr><th scope=\"row\">Côte d’Ivoire</th><td>72 133 (A)</td><td>599 673 (I)</td><td>120,30 (E)</td></tr><tr><th scope=\"row\">Guinée</th><td>174 847,18 (I)</td><td>445 086 (I)</td><td>392,80 (E)</td></tr><tr><th scope=\"row\">Togo</th><td>21 769,41 (I)</td><td>42 200 (I)</td><td>515,90 (E)</td></tr><tr><th scope=\"row\">Sierra Leone</th><td>2 208,05 (I)</td><td>1 499 (I)</td><td>1 472,70 (E)</td></tr><tr><th scope=\"row\">Ghana</th><td>736 (E)</td><td>460 (E)</td><td>1 600 (E)</td></tr><tr><th scope=\"row\">Nigeria</th><td>1 808,66 (E)</td><td>1 379 (E)</td><td>1 312 (E)</td></tr><tr><th scope=\"row\">Liberia</th><td>653,22 (I)</td><td>2 753 (I)</td><td>237,30 (E)</td></tr><tr><th scope=\"row\">Bénin</th><td>55,13 (E)</td><td>284 (E)</td><td>194,50 (E)</td></tr></tbody></table></div><p class=\"muted small\">Sur téléphone, faites défiler le tableau horizontalement pour lire toutes les colonnes. Ouvrez ensuite une fiche pays.</p><details class=\"acc\"><summary>Côte d’Ivoire : données et limites</summary><div class=\"acc-body\"><p>Production de café vert : 2022, 89 878 (A) t ; 2023, 46 975 (A) t ; 2024, 72 133 (A) t [[faowest]].</p><p>La production 2024 porte le drapeau A, mais la surface est imputée et le rendement estimé. Le bulletin USDA de juillet 2026 donne séparément 650 000 sacs en 2024/25 et 1,3 million en 2025/26 [[usda]]. Ne pas raccorder directement tonnes annuelles FAOSTAT et sacs par campagne USDA.</p><p><strong>À documenter :</strong> validation nationale récente, régions de production, espèces cultivées, transformation, prix aux producteurs et acteurs vérifiés. Ces champs ne sont pas remplis avec les données d’un pays voisin.</p></div></details><details class=\"acc\"><summary>Guinée : données et limites</summary><div class=\"acc-body\"><p>Production de café vert : 2022, 261 645 (A) t ; 2023, 200 000 (X) t ; 2024, 174 847,18 (I) t [[faowest]].</p><p>Écart majeur entre sources : FAOSTAT donne 174 847,18 t en 2024 (I), alors que l’OIC donnait une moyenne de 374 000 sacs, soit 22 440 t après conversion, pour 2010/11–2013/14 [[icoafrica]]. Les périodes diffèrent, mais cela ne suffit pas à expliquer cet écart. La surface FAOSTAT 2024 (445 086 ha, I) diffère aussi des 46 000 ha du tableau OIC ancien. Aucun taux de croissance ni classement récent n’est déduit de ces séries avant recoupement national.</p><p><strong>À documenter :</strong> validation nationale récente, régions de production, espèces cultivées, transformation, prix aux producteurs et acteurs vérifiés. Ces champs ne sont pas remplis avec les données d’un pays voisin.</p></div></details><details class=\"acc\"><summary>Togo : données et limites</summary><div class=\"acc-body\"><p>Production de café vert : 2022, 25 132 (A) t ; 2023, 22 619,45 (I) t ; 2024, 21 769,41 (I) t [[faowest]].</p><p>La production et la surface 2024 sont imputées, le rendement estimé. Les 40 000 ha du tableau OIC ancien et les 42 200 ha récoltés FAOSTAT ne portent ni la même période ni nécessairement la même définition [[icoafrica]]. Les rapprocher ne démontre pas une extension mesurée du verger.</p><p><strong>À documenter :</strong> validation nationale récente, régions de production, espèces cultivées, transformation, prix aux producteurs et acteurs vérifiés. Ces champs ne sont pas remplis avec les données d’un pays voisin.</p></div></details><details class=\"acc\"><summary>Sierra Leone : données et limites</summary><div class=\"acc-body\"><p>Production de café vert : 2022, 2 580 (X) t ; 2023, 2 333,16 (A) t ; 2024, 2 208,05 (I) t [[faowest]].</p><p>La production et la surface 2024 sont imputées, le rendement estimé. Les 1 499 ha récoltés FAOSTAT ne doivent pas être confondus avec une surface plantée totale. Le tableau OIC de 2015 donne d’autres surfaces selon ses tableaux, dont 15 000 ha au tableau 7 : périmètre à éclaircir [[icoafrica]].</p><p><strong>À documenter :</strong> validation nationale récente, régions de production, espèces cultivées, transformation, prix aux producteurs et acteurs vérifiés. Ces champs ne sont pas remplis avec les données d’un pays voisin.</p></div></details><details class=\"acc\"><summary>Ghana : données et limites</summary><div class=\"acc-body\"><p>Production de café vert : 2022, 736 (E) t ; 2023, 736 (E) t ; 2024, 736 (E) t [[faowest]].</p><p>Les trois indicateurs 2024 sont estimés. La production et la surface sont identiques dans le fichier de 2018 à 2024 (736 t et 460 ha). Cette stabilité statistique ne prouve pas une stabilité observée sur le terrain. Les anciennes estimations OIC sont très différentes : aucune évolution de long terme n’est calculée [[icoafrica]].</p><p><strong>À documenter :</strong> validation nationale récente, régions de production, espèces cultivées, transformation, prix aux producteurs et acteurs vérifiés. Ces champs ne sont pas remplis avec les données d’un pays voisin.</p></div></details><details class=\"acc\"><summary>Nigeria : données et limites</summary><div class=\"acc-body\"><p>Production de café vert : 2022, 1 819,02 (E) t ; 2023, 1 808,01 (E) t ; 2024, 1 808,66 (E) t [[faowest]].</p><p>Les trois indicateurs 2024 sont estimés. Les 1 379 ha récoltés du fichier FAOSTAT sont très éloignés des surfaces anciennes de l’OIC, qui varient elles-mêmes selon les tableaux [[icoafrica]]. Ces séries sont conservées comme données de sources différentes, sans les fusionner.</p><p><strong>À documenter :</strong> validation nationale récente, régions de production, espèces cultivées, transformation, prix aux producteurs et acteurs vérifiés. Ces champs ne sont pas remplis avec les données d’un pays voisin.</p></div></details><details class=\"acc\"><summary>Liberia : données et limites</summary><div class=\"acc-body\"><p>Production de café vert : 2022, 655,85 (I) t ; 2023, 654,58 (I) t ; 2024, 653,22 (I) t [[faowest]].</p><p>La production et la surface 2024 sont imputées, le rendement estimé. L’OIC donnait une moyenne de 10 000 sacs pour 2010/11–2013/14 [[icoafrica]], soit 600 t après conversion du site. La proximité avec FAOSTAT ne valide pas pour autant une continuité statistique.</p><p><strong>À documenter :</strong> validation nationale récente, régions de production, espèces cultivées, transformation, prix aux producteurs et acteurs vérifiés. Ces champs ne sont pas remplis avec les données d’un pays voisin.</p></div></details><details class=\"acc\"><summary>Bénin : données et limites</summary><div class=\"acc-body\"><p>Production de café vert : 2022, 55,30 (E) t ; 2023, 55,09 (E) t ; 2024, 55,13 (E) t [[faowest]].</p><p>Les trois indicateurs 2024 sont estimés. Le dossier Bénin confronte cette série aux archives, au décret de 2001 et aux publications agricoles nationales, sans affirmer de zones de culture actuelles. <a href=\"benin.html\">Lire le dossier Bénin et ses limites</a>.</p><p><strong>À documenter :</strong> validation nationale récente, régions de production, espèces cultivées, transformation, prix aux producteurs et acteurs vérifiés. Ces champs ne sont pas remplis avec les données d’un pays voisin.</p></div></details><p><strong>Périmètre :</strong> ces huit fiches couvrent les pays du tableau OIC ouest-africain reproduit plus haut, pas tous les États de la région. L’absence d’un autre pays dans ce tableau ne signifie pas absence de café, de commerce ou de consommation. Les chiffres historiques restent visibles et séparés. Une tonne équivaut à 1 000 kg ; un sac statistique à 60 kg. Les conversions sont des calculs du site, pas une nouvelle observation.</p>"],
 ['Éthiopie, berceau de l’Arabica','<p>L’Éthiopie a enregistré la croissance la plus dynamique de la production africaine : +2,7 % par an en moyenne sur 43 ans, et +5,5 % par an depuis 1990 (rapport OIC de 2015) [[icoafrica]].</p>'],
 ['Ouganda','<p>La production ougandaise a baissé de 6,8 % en 2022/23 à 5,6 millions de sacs (6,0 en 2021/22) [[ico23]]. Bulletin USDA de juillet 2026 : 7,095 millions de sacs en 2025/26 (robusta 5,975 M, arabica 1,12 M) et 7,16 M prévus pour 2026/27 ; l’Ouganda est le 4e producteur mondial de robusta dans ce tableau, derrière le Vietnam, le Brésil et l’Indonésie [[usda]].</p>'],
 ['Producteurs africains : repères USDA 2025/26','<p>Bulletin Coffee: World Markets and Trade de l’USDA (Foreign Agricultural Service), juillet 2026, tableau « Coffee Summary », production totale en milliers de sacs de 60 kg ; le bulletin donne aussi 2021/22 à 2023/24. 2025/26 est l’estimation du bulletin et 2026/27 sa prévision ; chaque pays suit sa propre année de commercialisation : octobre à septembre pour l’Éthiopie, l’Ouganda, la Côte d’Ivoire et le Kenya, juillet à juin pour la Tanzanie [[usda]].</p><div class="tbl-wrap"><table class="tbl tbl-sm"><caption>Production (milliers de sacs de 60 kg), USDA, juillet 2026</caption><thead><tr><th scope="col">Pays</th><th scope="col">2024/25</th><th scope="col">2025/26</th><th scope="col">2026/27 (prév.)</th></tr></thead><tbody><tr><th scope="row">Éthiopie</th><td>11 460</td><td>11 560</td><td>12 100</td></tr><tr><th scope="row">Ouganda</th><td>6 700</td><td>7 095</td><td>7 160</td></tr><tr><th scope="row">Côte d’Ivoire</th><td>650</td><td>1 300</td><td>1 300</td></tr><tr><th scope="row">Tanzanie</th><td>1 350</td><td>1 450</td><td>1 600</td></tr><tr><th scope="row">Kenya</th><td>950</td><td>850</td><td>950</td></tr></tbody></table></div><p>L’USDA prévoit pour l’Éthiopie un record de 12,1 millions de sacs en 2026/27, grâce à des surfaces et des rendements plus élevés, avec des exportations de café vert prévues à 7,1 millions de sacs [[usda]]. Le Cameroun, le Togo, le Rwanda et le Burundi figurent dans la liste des pays producteurs suivis par l’USDA (années de commercialisation : octobre à septembre pour le Cameroun et le Togo ; avril à mars pour le Rwanda et le Burundi), mais n’ont pas de ligne dédiée dans ce tableau [[usda]]. Pour ces pays, les repères sourcés restent ceux de l’OIC de 2015 présentés ci-dessous, qui ne sont pas des chiffres actuels [[icoafrica]]. Le Ghana n’est pas cité dans ce bulletin ; sa fiche ci-dessus apporte une série FAOSTAT distincte, estimée [[faowest]].</p>'],
 ['Autres pays africains','<p>Données de l’OIC, rapport ICC-114-5 de 2015 (annexe, tableaux 1 et 3) : production moyenne par décennie et estimation 2013/14, en milliers de sacs de 60 kg ; nombre de producteurs et superficie estimés. Le rapport est publié en 2015 ; l’année d’observation des producteurs et superficies n’est pas précisée, et la production 2013/14 est une estimation. Ce ne sont pas des chiffres actuels [[icoafrica]].</p><div class="tbl-wrap"><table class="tbl"><caption>Production (milliers de sacs de 60 kg), producteurs et superficie, d’après l’OIC (publication de 2015)</caption><thead><tr><th scope="col">Pays</th><th scope="col">Années 1980</th><th scope="col">Années 2000</th><th scope="col">2013/14 (estim.)</th><th scope="col">Producteurs</th><th scope="col">Superficie (ha)</th></tr></thead><tbody><tr><th scope="row">Côte d’Ivoire</th><td>4 338</td><td>2 692</td><td>2 100</td><td>650 000</td><td>360 000</td></tr><tr><th scope="row">Cameroun</th><td>1 771</td><td>834</td><td>315</td><td>650 000</td><td>140 000</td></tr><tr><th scope="row">Tanzanie</th><td>875</td><td>793</td><td>799</td><td>900 000</td><td>229 000</td></tr><tr><th scope="row">Kenya</th><td>1 726</td><td>766</td><td>750</td><td>700 000</td><td>160 000</td></tr><tr><th scope="row">Rwanda</th><td>583</td><td>314</td><td>246</td><td>700 000</td><td>42 000</td></tr><tr><th scope="row">Burundi</th><td>526</td><td>312</td><td>161</td><td>600 000</td><td>60 000</td></tr><tr><th scope="row">Togo</th><td>251</td><td>143</td><td>100</td><td>62 282</td><td>37 768</td></tr><tr><th scope="row">Ghana</th><td>12</td><td>29</td><td>60</td><td>4 182</td><td>35 000</td></tr><tr><th scope="row">Bénin</th><td>33</td><td>0</td><td>0</td><td>8 000</td><td>15 000</td></tr></tbody></table></div><p>Lecture : les chiffres sont recopiés tels que publiés ; la superficie du Ghana (35 000 ha pour 4 182 producteurs) semble atypique et n’est pas vérifiée ailleurs. Pour les années récentes, consulter la base de l’OIC [[icostats]]. Les fiches détaillées par pays restent à documenter.</p><h3>Chiffres récents (USDA)</h3><p>Le bulletin USDA FAS de juillet 2026 donne la production totale (arabica et robusta) en milliers de sacs de 60 kg. Les années sont celles du tableau « Coffee Summary » (page 7, en-têtes relus sur la page) ; la dernière colonne est étiquetée « Jul 2026/27 », la prévision de juillet 2026. Les années sont des campagnes commerciales propres à chaque pays, pas des années civiles, et le bulletin révise ses chiffres d’une édition à l’autre : par exemple la Côte d’Ivoire 2024/25 est à 650 dans cette édition [[usda]].</p><div class="tbl-wrap"><table class="tbl"><caption>Production totale, milliers de sacs de 60 kg (USDA, juillet 2026)</caption><thead><tr><th scope="col">Pays</th><th scope="col">2023/24</th><th scope="col">2024/25</th><th scope="col">2025/26</th><th scope="col">2026/27 (prévision de juillet 2026)</th></tr></thead><tbody><tr><th scope="row">Éthiopie</th><td>9 130</td><td>11 460</td><td>11 560</td><td>12 100</td></tr><tr><th scope="row">Ouganda</th><td>6 400</td><td>6 700</td><td>7 095</td><td>7 160</td></tr><tr><th scope="row">Tanzanie</th><td>1 350</td><td>1 350</td><td>1 450</td><td>1 600</td></tr><tr><th scope="row">Côte d’Ivoire</th><td>1 325</td><td>650</td><td>1 300</td><td>1 300</td></tr><tr><th scope="row">Kenya</th><td>825</td><td>950</td><td>850</td><td>950</td></tr></tbody></table></div><p>Cameroun, Rwanda, Burundi, Togo, Ghana et Bénin ne figurent pas dans ce tableau USDA : une série FAOSTAT 2024 distincte est ajoutée ci-dessus pour le Togo, le Ghana et le Bénin [[faowest]] ; le recoupement OIC reste à faire [[icostats]].</p>']
 ],
 terms:['Robusta','Canephora'], refs:['ico23','usda','icoafrica','decret','faostatbj','terra','beanesis','iaco','iacoglance','ico1026','lanat','icostats','duprez','faobulk','faowest','dsa2324'] }
];
